"""依赖锁文件（``requirements.lock``）生成与校验.

``fspack --lock`` 在构建成功后把本次实际下载的 wheel 写成
``name==version --hash=sha256:<hex>``（每个 wheel 一行，按名称排序），
输出到项目根目录。同一输入（py 版本/平台/依赖声明/索引）跨日构建结果一致，
便于提交到仓库供 CI 复用。

``fspack --frozen`` 读取该文件：以锁文件中的精确版本作为下载目标，并校验
每个 wheel 的 sha256。锁文件缺失、缺少某依赖或哈希不符时抛
:class:`DependencyError`，不静默降级。

格式（pip requirements 兼容子集）：:

    # Generated by fspack --lock; do not edit.
    # python=3.11.9 platform=windows index=https://...
    numpy==1.26.4 --hash=sha256:<hex>
    pillow==10.4.0 --hash=sha256:<hex> --hash=sha256:<hex>

不做时间戳/随机顺序，保证可复现；同一 ``name==version`` 的多个平台 wheel
合并到一行（多个 ``--hash``）。
"""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from pathlib import Path

from fspack.exceptions import DependencyError

__all__ = [
    "LOCK_FILE_NAME",
    "RequirementsLock",
    "read_requirements_lock",
    "verify_wheels_against_lock",
    "write_requirements_lock",
]

LOCK_FILE_NAME = "requirements.lock"

# name==version 后跟一个或多个 --hash=sha256:<64 hex>
_LINE_RE = re.compile(
    r"^(?P<spec>[A-Za-z0-9][A-Za-z0-9._-]*)==(?P<version>[^\s;]+)"
    r"(?P<hashes>(?:\s+--hash=sha256:[0-9a-fA-F]{64})+)\s*$"
)
_HASH_RE = re.compile(r"--hash=sha256:([0-9a-fA-F]{64})")

_HEADER_KEYS = ("python", "platform", "index")


@dataclass(frozen=True)
class RequirementsLock:
    """解析后的锁文件内容."""

    # 文件元信息（python/platform/index），用于诊断锁文件是否对应当前构建目标
    metadata: dict[str, str]
    # name==version（按名称排序）
    requirements: tuple[str, ...]
    # 归一化包名 → wheel sha256 集合（小写）
    hashes: dict[str, frozenset[str]]


def _sha256_file(path: Path, *, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        while chunk := f.read(chunk_size):
            digest.update(chunk)
    return digest.hexdigest()


def _normalize(name: str) -> str:
    """PEP 503 归一化包名（与 site_packages.normalize_pkg_name 一致）."""
    return re.sub(r"[-_.]+", "-", name).lower()


def write_requirements_lock(
    path: Path,
    wheels: list[Path] | tuple[Path, ...],
    *,
    py_version: str,
    platform: str,
    index: str,
) -> Path:
    """把已下载的 wheel 写成锁文件，返回写入路径.

    Args:
        path: 输出路径（通常为 ``<project>/requirements.lock``）。
        wheels: 本次实际安装的 wheel 路径列表。
        py_version: 目标 Python 版本（写入头部注释）。
        platform: 目标平台（写入头部注释）。
        index: PyPI 索引地址（写入头部注释）。

    Raises:
        DependencyError: wheel 文件名无法解析出包名/版本。
    """
    grouped: dict[str, list[str]] = {}
    # 延迟导入：fspack.slim 会加载进度/控制台模块，锁文件在 CLI 快速路径上只需
    # 名称与版本解析，避免拖慢 ``import fspack.builder``（见 test_cli 的惰性导入断言）
    from fspack.slim.spec import WheelInfo

    for wheel in sorted(wheels, key=lambda p: p.name):
        info = WheelInfo.from_filename(wheel.name)
        if info is None:
            raise DependencyError(f"无法从 wheel 文件名解析包名/版本，无法写入锁文件: {wheel.name}")
        spec = f"{_normalize(info.name)}=={info.version}"
        grouped.setdefault(spec, []).append(_sha256_file(wheel))
    lines = [
        "# Generated by fspack --lock; do not edit.",
        f"# python={py_version}",
        f"# platform={platform}",
        f"# index={index}",
        "# 提交本文件后可用 fspack --frozen 复现同一依赖集合与 sha256",
    ]
    for spec in sorted(grouped):
        hashes = " ".join(f"--hash=sha256:{digest}" for digest in sorted(set(grouped[spec])))
        lines.append(f"{spec} {hashes}")
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return path


def read_requirements_lock(path: Path) -> RequirementsLock:
    """读取并解析锁文件.

    Raises:
        DependencyError: 文件不存在、行格式非法或没有任何依赖行。
    """
    if not path.is_file():
        raise DependencyError(
            f"--frozen 需要依赖锁文件 {path}，但文件不存在。请先在联网环境执行 `fspack --lock` 生成并提交该文件"
        )
    metadata: dict[str, str] = {}
    requirements: list[str] = []
    hashes: dict[str, frozenset[str]] = {}
    for lineno, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        line = raw.strip()
        if not line:
            continue
        if line.startswith("#"):
            # 头部注释里的 key=value 写回元信息，便于提示锁文件与目标不匹配
            body = line.lstrip("# ").strip()
            key, sep, value = body.partition("=")
            if sep and key in _HEADER_KEYS and value.strip():
                metadata[key] = value.strip()
            continue
        m = _LINE_RE.match(line)
        if m is None:
            raise DependencyError(
                f"依赖锁文件格式非法（第 {lineno} 行）: {line!r}。每行应为 `name==version --hash=sha256:<64 hex>`"
            )
        name = _normalize(m.group("spec"))
        spec = f"{name}=={m.group('version')}"
        requirements.append(spec)
        digests = frozenset(d.lower() for d in _HASH_RE.findall(m.group("hashes")))
        hashes[name] = hashes.get(name, frozenset()) | digests
    if not requirements:
        raise DependencyError(f"依赖锁文件不含任何依赖行: {path}")
    return RequirementsLock(metadata=metadata, requirements=tuple(requirements), hashes=hashes)


def verify_wheels_against_lock(wheels: list[Path] | tuple[Path, ...], lock: RequirementsLock) -> None:
    """校验下载的 wheel 与锁文件完全一致（双向）.

    - 每个 wheel 的包名必须出现在锁文件中，且 sha256 命中声明的集合
    - 锁文件中的每个依赖都必须有对应 wheel（新增依赖后忘记重新生成锁文件
      时会在这里失败，而不是悄悄产出不同的依赖集合）

    Raises:
        DependencyError: 包名缺失、sha256 不符，或锁文件中的依赖未出现在下载结果中。
    """
    covered: set[str] = set()
    from fspack.slim.spec import WheelInfo

    for wheel in wheels:
        info = WheelInfo.from_filename(wheel.name)
        if info is None:
            raise DependencyError(f"无法从 wheel 文件名解析包名，无法校验锁文件: {wheel.name}")
        name = _normalize(info.name)
        covered.add(name)
        allowed = lock.hashes.get(name)
        if allowed is None:
            raise DependencyError(
                f"依赖 {name} 不在 requirements.lock 中（wheel {wheel.name}）；请重新执行 `fspack --lock` 更新锁文件"
            )
        actual = _sha256_file(wheel)
        if actual not in allowed:
            raise DependencyError(
                f"{wheel.name} 的 sha256 与 requirements.lock 不符: 期望 {sorted(allowed)}，实际 {actual}；"
                "锁文件可能被篡改或索引返回了不同构建，请重新生成锁文件"
            )
    missing = sorted(set(lock.hashes) - covered)
    if missing:
        raise DependencyError(
            f"requirements.lock 中的依赖未出现在本次下载结果: {', '.join(missing)}；"
            "锁文件与当前依赖声明/目标平台不一致，请重新执行 `fspack --lock`"
        )
